export function deleteFiles(files: JsonValue): void {
  try {
    if (!files) return;

    if (Array.isArray(files)) {
      for (const val of files) {
        if (typeof val === "string") unlinkFile(val);
      }
      return;
    }

    if (typeof files === "string") {
      unlinkFile(files);
      return;
    }
  } catch (err) {
    console.error("❌ deleteFiles() error:", err);
  }
}
